<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\ShippingZone; use Illuminate\Http\Request;
class ShippingZoneController extends Controller { public function index(){return view('admin.shipping-zones.index',['zones'=>ShippingZone::orderBy('sort_order')->get()]);} public function create(){return view('admin.shipping-zones.form',['zone'=>new ShippingZone]);} public function store(Request $r){ShippingZone::create($this->data($r));return to_route('admin.shipping-zones.index')->with('success','Zone saved.');} public function edit(ShippingZone $shippingZone){return view('admin.shipping-zones.form',['zone'=>$shippingZone]);} public function update(Request $r,ShippingZone $shippingZone){$shippingZone->update($this->data($r));return to_route('admin.shipping-zones.index')->with('success','Zone updated.');} public function destroy(ShippingZone $shippingZone){$shippingZone->delete();return back()->with('success','Zone removed.');} private function data(Request $r){return $r->validate(['name'=>'required|string|max:255','state'=>'required|string|max:120','city_or_area'=>'nullable|string|max:120','postcode_from'=>'nullable|string|max:20','postcode_to'=>'nullable|string|max:20','base_fee'=>'required|numeric|min:0','sort_order'=>'required|integer|min:0','is_active'=>'nullable|boolean'])+['is_active'=>$r->boolean('is_active')];}}
